<?php
namespace Modules\BankingMicrofinance\Http\Controllers;use Illuminate\Http\Request;use Modules\BankingMicrofinance\Entities\GroupMeeting;use Modules\BankingMicrofinance\Entities\GroupMeetingAttendance;
class GroupMeetingController extends Controller{public function index(){$items=GroupMeeting::latest('meeting_date')->paginate(25);return view('bankingmicrofinance::group_meetings.index',compact('items'));}public function create(){return view('bankingmicrofinance::group_meetings.form',['item'=>new GroupMeeting()]);}public function store(Request $request){GroupMeeting::create($request->all()+['created_by'=>auth()->id()]);return redirect()->route('banking-microfinance.group-meetings.index')->with('status','Meeting saved.');}public function edit(GroupMeeting $group_meeting){return view('bankingmicrofinance::group_meetings.form',['item'=>$group_meeting]);}public function update(Request $request,GroupMeeting $group_meeting){$group_meeting->update($request->all());return redirect()->route('banking-microfinance.group-meetings.index')->with('status','Meeting updated.');}public function attendance(GroupMeeting $group_meeting){$rows=GroupMeetingAttendance::where('meeting_id',$group_meeting->id)->get();return view('bankingmicrofinance::group_meetings.attendance',compact('group_meeting','rows'));}public function saveAttendance(Request $request,GroupMeeting $group_meeting){foreach(($request->attendance??[]) as $memberId=>$row){GroupMeetingAttendance::updateOrCreate(['meeting_id'=>$group_meeting->id,'member_id'=>$memberId],$row+['business_id'=>$group_meeting->business_id]);}return back()->with('status','Attendance saved.');}}
